'use strict';
const root=document.getElementById('app');
const state={user:null,csrf:null,permissions:[],privateCosts:false,route:'dashboard',catalog:{},current:null};
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c='CAD')=>new Intl.NumberFormat('en-CA',{style:'currency',currency:c}).format(Number(n??0)/100);
const today=()=>new Date().toISOString().slice(0,10);
const plusDays=n=>{const d=new Date();d.setUTCDate(d.getUTCDate()+Number(n));return d.toISOString().slice(0,10);};
const names={dashboard:'Dashboard',customers:'Customers',estimates:'Estimates',invoices:'Invoices',sales_orders:'Sales Orders',purchase_orders:'Purchase Orders',products:'Products',suppliers:'Suppliers',projects:'Projects',payments:'Payments',reports:'Reports',settings:'Settings'};
const kindRoute={estimate:'estimates',invoice:'invoices',purchase_order:'purchase_orders',sales_order:'sales_orders'};
const routeKind={estimates:'estimate',invoices:'invoice',purchase_orders:'purchase_order',sales_orders:'sales_order'};
const singular={customers:'Customer',suppliers:'Supplier',products:'Product',projects:'Project'};
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',customers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 8v6 M17 11h6',products:'M3 7l9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5 M12 12v10',reports:'M4 20h16 M7 16V9 M12 16V4 M17 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',documents:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7'};
const icon=key=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[key]??icons.documents}"/></svg>`;
const can=(r,w=false)=>(state.permissions.includes('*')||state.permissions.includes(r))&&!(w&&state.user?.role==='Read Only');
async function api(url,options={}){const response=await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf??'',...options.headers}});const body=await response.json();if(!response.ok){if(response.status===401&&state.user){state.user=null;await initialize();}throw new Error(body.error??'Action failed');}return body;}
const post=(url,data={})=>api(url,{method:'POST',body:JSON.stringify(data)});
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.className='visible';clearTimeout(toast.timer);toast.timer=setTimeout(()=>{t.className='';t.textContent='';},5500);}
function fail(error){toast(error.message??String(error));}
function badge(status){const cls=['Paid','Accepted','Received','Completed','Shipped','Acknowledged'].includes(status)?'good':['Overdue','Void','Failed','Cancelled','Declined','Expired'].includes(status)?'bad':['Partial','Partially Received','Waiting for Parts','Sent'].includes(status)?'warn':'';return `<span class="badge ${cls}">${E(status)}</span>`;}
function head(title,buttons='',subtitle=''){return `<div class="page-head"><div><div class="eyebrow">Elevated Operations</div><h1>${E(title)}</h1>${subtitle?`<p>${E(subtitle)}</p>`:''}</div><div class="actions">${buttons}</div></div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${E(title)}</h2>${action}</div>${body}</section>`;}
function empty(title,text){return `<div class="empty"><strong>${E(title)}</strong>${E(text)}</div>`;}
function btn(label,attrs='',cls=''){return `<button class="btn ${cls}" ${attrs}>${E(label)}</button>`;}
function bind(selector,event,fn){document.querySelectorAll(selector).forEach(el=>el.addEventListener(event,fn));}
function render(html){document.getElementById('content').innerHTML=html;document.getElementById('content').querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',e=>navigate(e.currentTarget.dataset.nav)));bind('[data-doc]','click',e=>openDocument(e.currentTarget.dataset.doc).catch(fail));bind('[data-record]','click',e=>openRecord(e.currentTarget.dataset.table,e.currentTarget.dataset.record).catch(fail));bind('[data-new]','click',e=>startNew(e.currentTarget.dataset.new).catch(fail));}
function shell(){root.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand">ELEVATED<small>AUTOMATIC DOOR PARTS</small></div><nav class="nav">${Object.keys(names).filter(r=>can(r)&&(r!=='reports'||state.privateCosts)).map(r=>`<button data-nav="${r}" class="${state.route===r?'active':''}">${icon(r)}${names[r]}</button>`).join('')}</nav><div class="sidebar-footer">OPERATIONS PLATFORM<br>CAD · Independent business system</div></aside><div class="workspace"><header class="topbar">${btn('☰','id="mobile-menu" aria-label="Open navigation"','mobile-menu')}<div class="search-wrap"><input class="global-search" id="global-search" placeholder="Search customers, SKUs, documents, customer POs…" aria-label="Search all records"><div id="search-results"></div></div><div class="user"><div class="avatar">${E(state.user.name.slice(0,2).toUpperCase())}</div><div class="user-name">${E(state.user.name)}<small>${E(state.user.role)}</small></div>${btn('Sign out','id="logout"','link')}</div></header><main class="content" id="content"></main></div></div>`;
 bind('.nav [data-nav]','click',e=>navigate(e.currentTarget.dataset.nav));document.getElementById('mobile-menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('logout').onclick=async()=>{try{await post('/auth/logout');state.user=null;await initialize();}catch(e){fail(e);}};
 let timer;document.getElementById('global-search').addEventListener('input',e=>{clearTimeout(timer);timer=setTimeout(async()=>{try{const results=await api('/search?q='+encodeURIComponent(e.target.value));const box=document.getElementById('search-results');box.innerHTML=results.length?`<div class="search-results">${results.map(r=>`<button data-result="${r.id}" data-type="${r.type}">${E(r.label)} <span class="subtle">· ${E(r.type)}</span></button>`).join('')}</div>`:'';bind('[data-result]','click',async e=>{const b=e.currentTarget;box.innerHTML='';document.getElementById('global-search').value='';try{if(b.dataset.type==='document')await openDocument(b.dataset.result);else await openRecord({customer:'customers',supplier:'suppliers',product:'products',project:'projects'}[b.dataset.type],b.dataset.result);}catch(error){fail(error);}});}catch(error){fail(error);}},250);});
}
async function initialize(){try{const status=await api('/auth/status');try{const me=await api('/auth/me');Object.assign(state,{user:me.user,csrf:me.csrf,permissions:me.permissions,privateCosts:me.private_costs});shell();await navigate('dashboard');}catch{login(!status.configured);}}catch(error){root.innerHTML=`<div class="login-card"><h2>Unable to connect</h2><p>${E(error.message)}</p><button class="btn" id="retry">Try again</button></div>`;document.getElementById('retry').onclick=initialize;}}
function login(setup){const token=new URLSearchParams(location.hash.slice(1)).get('setup')??'';if(token)history.replaceState(null,'',location.pathname);root.innerHTML=`<div class="login-page"><div class="login-brand"><div class="wordmark">ELEVATED / OPERATIONS</div><h1>Your business.<br>Connected from<br>quote to payment.</h1><p>One workspace for your customers, parts, purchasing, and financial documents.</p></div><div class="login-card"><h2>${setup?'Set up your owner account':'Welcome back'}</h2><p>${setup?'Create the private owner account for Elevated Automatic Door Parts. Use a password of at least 12 characters.':'Sign in to Elevated Automatic Door Parts.'}</p><div id="login-error"></div><form id="login-form">${setup?field('name','Your name','text','',true):''}${field('email','Email','email','',true)}${field('password','Password','password','',true)}${setup&&!token?field('token','Private setup key','password','',true):''}${btn(setup?'Create owner account':'Sign in','type="submit"','primary')}</form><div class="login-foot">Private business application · Secure session</div></div></div>`;document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(setup)data.token=token||data.token;const result=await post(setup?'/auth/setup':'/auth/login',data);state.user=result.user;state.csrf=result.csrf;await initialize();}catch(error){document.getElementById('login-error').innerHTML=`<div class="error">${E(error.message)}</div>`;}finally{button.disabled=false;}};}
async function navigate(route){state.route=route;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===route));document.getElementById('sidebar')?.classList.remove('open');render('<div class="loading">Loading…</div>');try{if(route==='dashboard')return await dashboard();if(routeKind[route])return await documentList(routeKind[route]);if(['customers','suppliers','products','projects'].includes(route))return await recordList(route);if(route==='payments')return await paymentsPage();if(route==='reports')return await reportsPage();if(route==='settings')return await settingsPage();}catch(error){render(head(names[route])+`<div class="error">${E(error.message)}</div>`);}}
function metric(label,value,note='',accent=false){return `<div class="metric ${accent?'accent':''}"><label>${E(label)}</label><strong>${E(value)}</strong><small>${E(note)}</small></div>`;}
async function dashboard(){const d=await api('/dashboard');const financial=d.revenue_month!==null;const metrics=financial?[metric('Revenue this month',money(d.revenue_month),'Invoiced sales, before tax',true),metric('Outstanding invoices',money(d.outstanding),'Remaining customer balances'),metric('Gross profit this month',money(d.gross_profit),'Based on saved product costs'),metric('Gross margin',d.gross_margin===null?'—':d.gross_margin.toFixed(1)+'%','This month, before tax')]:[metric('Open estimates',d.open_estimates,'Draft and awaiting response',true),metric('Accepted estimates',d.accepted_estimates,'Accepted and converted'),metric('Open purchase orders',d.open_purchase_orders,'Orders requiring follow-up'),metric('Awaiting delivery',d.awaiting_delivery,'Supplier shipments')];const quick=[['estimates','+ New Estimate'],['invoices','+ New Invoice'],['purchase_orders','+ New Purchase Order'],['customers','+ New Customer'],['suppliers','+ New Supplier'],['products','+ New Product'],['payments','+ Record Payment']].filter(([r])=>can(r,true)&&(r!=='products'||state.privateCosts)).map(([r,label])=>btn(label,`data-new="${r}"`)).join('');render(head('Dashboard','',new Intl.DateTimeFormat('en-CA',{dateStyle:'long'}).format(new Date()))+`<div class="grid metrics">${metrics.join('')}</div><div class="quick-actions">${quick}</div><div class="dashboard-grid"><div>${panel('Recent documents',d.recent_documents.length?docTable(d.recent_documents):empty('Your workspace is ready','Create your first customer and estimate to begin.'),btn('View estimates','data-nav="estimates"','small'))}${panel('Business overview',`<div class="panel-body grid metrics">${metric('Revenue this year',financial?money(d.revenue_year):'—','Before tax')}${metric('Overdue invoices',financial?money(d.overdue):'—','Unpaid past due')}${metric('Open estimates',d.open_estimates,d.accepted_estimates+' accepted')}${metric('Supplier POs awaiting delivery',d.awaiting_delivery,d.open_purchase_orders+' open purchase orders')}</div>`)}${panel('Recent payments',d.recent_payments.length?simpleTable(['Invoice','Date','Amount'],d.recent_payments.map(p=>[E(p.number),E(String(p.date).slice(0,10)),money(p.amount_cents,p.currency)])):empty('No payments recorded','Recorded payments will appear here.'))}</div><div>${panel('Needs attention',d.attention.length?d.attention.map(x=>`<div class="attention-item"><div><button class="doc-link" data-doc="${x.id}">${E(x.number)}</button><small>${E(x.kind==='invoice'?'Payment overdue':x.kind==='purchase_order'?'Awaiting acknowledgement':x.kind==='estimate'?'Estimate expiring':'Waiting for supplier parts')}</small></div>${badge(x.status)}</div>`).join(''):empty('All caught up','No documents require attention.'))}${panel('Low-stock products',d.low_stock.length?d.low_stock.map(p=>`<div class="attention-item"><div><button class="doc-link" data-record="${p.id}" data-table="products">${E(p.name)}</button><small>${E(p.sku)}</small></div><div>${E(Number(p.stock_quantity))} on hand</div></div>`).join(''):empty('No low-stock alerts','Reorder points are managed in Products.'))}${panel('Recent customers',d.recent_customers.length?d.recent_customers.map(c=>`<div class="attention-item"><div><button class="doc-link" data-record="${c.id}" data-table="customers">${E(c.company)}</button><small>${E(c.contact)}</small></div></div>`).join(''):empty('No customers yet','Add companies and contractors here.'))}</div></div>`);}
function simpleTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function docTable(rows){return simpleTable(['Document','Customer / Supplier','Status','Date','Total'],rows.map(d=>[`<button class="doc-link" data-doc="${d.id}">${E(d.number)}</button>${d.customer_po?`<small>PO ${E(d.customer_po)}</small>`:''}`,E(d.party_snapshot.name),badge(displayStatus(d)),E(String(d.issue_date).slice(0,10)),money(d.total_cents,d.currency)]));}
function displayStatus(d){if(d.kind==='invoice'&&!['Draft','Void','Paid'].includes(d.status)&&d.due_date&&String(d.due_date).slice(0,10)<today()&&Number(d.total_cents)>Number(d.amount_paid_cents??d.paid??0))return 'Overdue';return d.status;}
async function documentList(kind){const rows=await api('/documents?kind='+kind);const route=kindRoute[kind];render(head(names[route],can(route,true)?btn('+ New '+({estimate:'Estimate',invoice:'Invoice',purchase_order:'Purchase Order',sales_order:'Sales Order'}[kind]),`data-new="${route}"`,'primary'):'')+`<section class="panel"><div class="toolbar"><input id="table-filter" placeholder="Search number, company, status, customer PO…" aria-label="Filter documents"><span>${rows.length} documents</span></div><div id="list-results">${rows.length?docTable(rows):empty('No '+names[route].toLowerCase()+' yet','Create your first document to begin.')}</div></section>`);document.getElementById('table-filter').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#list-results tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q));};}
async function getCatalog(table,force=false){if(force||!state.catalog[table])state.catalog[table]=await api('/'+table);return state.catalog[table];}

async function recordList(table){const rows=await getCatalog(table,true);const canEdit=can(table,true)&&(table!=='products'||state.privateCosts);let headers,cells;if(table==='customers'){headers=['Company','Contact','Email','Phone','Type / Tier'];cells=r=>[r.company,r.contact,r.email,r.phone,r.customer_type+' / '+r.pricing_tier];}else if(table==='suppliers'){headers=['Supplier','Contact','Email','Currency','Status'];cells=r=>[r.name,r.contact,r.email,r.currency,r.active?'Active':'Inactive'];}else if(table==='products'){const inventory=await api('/inventory');const invMap=new Map(inventory.map(x=>[x.id,x]));headers=['Product / SKU','Brand / Category','List price','Contractor price','On hand','Reserved','Available','Incoming','Backordered',...(state.privateCosts?['Cost / Margin']:[])];cells=r=>[r.name+'\n'+r.sku,r.brand+' / '+r.category,money(r.list_price_cents),money(r.contractor_price_cents),Number(r.stock_quantity),Number(invMap.get(r.id)?.reserved??0),Number(invMap.get(r.id)?.available??0),Number(invMap.get(r.id)?.incoming??0),Number(invMap.get(r.id)?.backordered??0),...(state.privateCosts?[money(r.cost_cents)+' / '+(Number(r.list_price_cents)?((Number(r.list_price_cents)-Number(r.cost_cents))/Number(r.list_price_cents)*100).toFixed(1)+'%':'—')]:[])];}else{headers=['Project','Number','Customer PO','Status'];cells=r=>[r.name,r.number,r.customer_po,r.status];}render(head(names[table],canEdit?btn('+ New '+singular[table],`data-new="${table}"`,'primary'):'',table==='customers'?'Customers, contractors, and dealers':'')+`<section class="panel"><div class="toolbar"><input id="table-filter" placeholder="Search ${E(names[table].toLowerCase())}…" aria-label="Filter ${E(names[table])}"><span>${rows.length} records</span></div>${rows.length?simpleTable(headers,rows.map(r=>cells(r).map((v,i)=>i===0?`<button class="doc-link" data-record="${r.id}" data-table="${table}">${E(String(v).split('\n')[0])}</button>${String(v).includes('\n')?`<small>${E(String(v).split('\n')[1])}</small>`:''}`:E(v)))):empty('No '+names[table].toLowerCase()+' yet','Add your first '+singular[table].toLowerCase()+'.')}</section>`);document.getElementById('table-filter').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q));};}
function field(name,label,type='text',value='',required=false,options=null,wide=false,help=''){let control;if(options)control=`<select name="${name}" id="f-${name}">${options.map(o=>{const val=typeof o==='string'?o:o.value,lab=typeof o==='string'?o:o.label;return `<option value="${E(val)}" ${String(value)===String(val)?'selected':''}>${E(lab)}</option>`;}).join('')}</select>`;else if(type==='textarea')control=`<textarea name="${name}" id="f-${name}">${E(value)}</textarea>`;else control=`<input name="${name}" id="f-${name}" type="${type}" value="${E(value)}" ${required?'required':''} ${type==='number'?'step="0.001" min="0"':''} ${type==='password'?'autocomplete="new-password" minlength="12" maxlength="72"':''}>`;return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${E(label)}</label>${control}${help?`<small>${E(help)}</small>`:''}</div>`;}
const tiers=['Retail','Contractor','Preferred Contractor','Dealer','Custom'];
const categories=['Guide Rails','Automatic Door Operators','Push Buttons','Activation Devices','Sensors','Transmitters','Receivers','Remote Posts','Door Hardware','Door Closers','Mounting Hardware','Automatic Door Parts','Accessories','Replacement Parts'];
async function startNew(route){if(routeKind[route])return documentEditor(routeKind[route]);if(route==='payments')return paymentEditor();return recordEditor(route);}
async function recordEditor(table,record={}){state.route=table;const r=record;let fields='';const f=(name,label,type='text',value=r[name]??'',required=false,opts=null,wide=false,help='')=>field(name,label,type,value,required,opts,wide,help);
 if(table==='customers')fields=f('company','Company name','text',r.company??'',true)+f('contact','Contact name')+f('email','Email','email')+f('phone','Phone')+f('billing_address','Billing address','textarea')+f('shipping_address','Shipping address','textarea')+f('customer_type','Customer type','text',r.customer_type??'Customer',false,['Customer','Contractor','Dealer'])+f('pricing_tier','Pricing tier','text',r.pricing_tier??'Retail',false,tiers)+f('tax_exempt','Tax status','text',String(r.tax_exempt??false),false,[{value:'false',label:'Taxable'},{value:'true',label:'Tax exempt'}])+f('account_status','Account status','text',r.account_status??'Active',false,['Active','On Hold','Inactive'])+f('payment_terms','Payment terms','text',r.payment_terms??'Net 30')+f('credit_terms','Credit terms')+f('notes','Notes','textarea',r.notes??'',false,null,true);
 if(table==='suppliers')fields=f('name','Supplier name','text',r.name??'',true)+f('contact','Contact name')+f('email','Email','email')+f('phone','Phone')+f('address','Address','textarea',r.address??'',false,null,true)+f('website','Website')+f('currency','Currency','text',r.currency??'CAD',false,['CAD','USD','CNY','EUR'])+f('payment_terms','Payment terms')+f('account_number','Account number')+f('shipping_terms','Shipping terms')+f('active','Account status','text',String(r.active??true),false,[{value:'true',label:'Active'},{value:'false',label:'Inactive'}])+f('notes','Notes','textarea',r.notes??'',false,null,true);
 if(table==='products')fields=f('sku','SKU','text',r.sku??'',true)+f('model','Model number')+f('name','Product name','text',r.name??'',true)+f('brand','Brand')+f('category','Category','text',r.category??'Automatic Door Parts',false,categories)+f('unit','Unit of measure','text',r.unit??'Each')+f('description','Description','textarea',r.description??'',false,null,true)+f('cost_cents','Cost (CAD)','number',Number(r.cost_cents??0)/100,true)+f('list_price_cents','List price (CAD)','number',Number(r.list_price_cents??0)/100,true)+f('contractor_price_cents','Contractor price (CAD)','number',Number(r.contractor_price_cents??0)/100)+f('stock_quantity','Quantity on hand','number',Number(r.stock_quantity??0))+f('reorder_point','Reorder point','number',Number(r.reorder_point??0))+f('lead_days','Lead time (days)','number',r.lead_days??0)+f('minimum_quantity','Minimum order quantity','number',Number(r.minimum_quantity??1))+f('taxable','Taxable','text',String(r.taxable??true),false,[{value:'true',label:'Yes'},{value:'false',label:'No'}])+f('notes','Notes','textarea',r.notes??'',false,null,true);
 if(table==='projects'){const customers=await getCatalog('customers');fields=f('name','Project name','text',r.name??'',true)+f('number','Project number','text',r.number??'',true)+f('customer_id','Customer','text',r.customer_id??'',true,[{value:'',label:'Choose customer'},...customers.map(c=>({value:c.id,label:c.company}))])+f('customer_po','Customer PO')+f('job_site','Job site')+f('contact','Contact')+f('status','Status','text',r.status??'Open',false,['Open','In Progress','Completed','Cancelled'])+f('notes','Notes','textarea',r.notes??'',false,null,true);}
 render(head((r.id?'Edit ':'New ')+singular[table],btn('Back',`data-nav="${table}"`))+`<form id="record-form" class="panel"><div class="panel-body"><div id="form-error"></div><div class="form-grid">${fields}</div><div class="form-footer">${btn('Cancel',`type="button" data-nav="${table}"`)}${btn('Save '+singular[table],'type="submit"','primary')}</div></div></form>`);document.getElementById('record-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type="submit"]');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));for(const key of Object.keys(data)){if(key.endsWith('_cents'))data[key]=Math.round(Number(data[key])*100);if(['stock_quantity','reorder_point','lead_days','minimum_quantity'].includes(key))data[key]=Number(data[key]);if(['tax_exempt','taxable','active'].includes(key))data[key]=data[key]==='true';}const saved=await api('/'+table+(r.id?'/'+r.id:''),{method:r.id?'PUT':'POST',body:JSON.stringify(data)});state.catalog[table]=null;toast(singular[table]+' saved');await openRecord(table,saved.id);}catch(error){document.getElementById('form-error').innerHTML=`<div class="error">${E(error.message)}</div>`;}finally{b.disabled=false;}};
}
async function openRecord(table,id){const rows=await getCatalog(table,true);const r=rows.find(x=>x.id===id);if(!r)throw new Error('Record not found');state.route=table;const canEdit=can(table,true)&&(table!=='products'||state.privateCosts);const details=Object.entries(r).filter(([k])=>!['id','created_at','updated_at'].includes(k)).map(([k,v])=>`<dt>${E(k.replaceAll('_',' ').replace(' cents',''))}</dt><dd>${E(k.endsWith('_cents')?money(v):typeof v==='boolean'?(v?'Yes':'No'):v)}</dd>`).join('');let extra='';if(table==='customers'){const s=await api('/customers/'+id+'/summary');extra=panel('Account overview',`<div class="panel-body grid metrics">${metric('Lifetime invoiced sales',money(s.lifetime_sales),'Before tax')}${metric('Outstanding balance',money(s.outstanding),'CAD equivalent')}</div>`)+panel('Documents',s.documents.length?simpleTable(['Document','Status','Total'],s.documents.map(d=>[`<button class="doc-link" data-doc="${d.id}">${E(d.number)}</button>`,badge(d.status),money(d.total_cents,d.currency)])):empty('No documents yet','Create an estimate for this account.'));}
 if(table==='products'&&can('suppliers')){const links=await api('/products/'+id+'/suppliers');extra=panel('Supplier sources',links.length?simpleTable(['Supplier','Supplier SKU','Cost','Lead time','Primary'],links.map(l=>[E(l.supplier_name),E(l.supplier_sku),money(l.cost_cents,l.currency),E(l.lead_days+' days'),l.is_primary?'Yes':'No'])):empty('No supplier sources','Link a supplier to enable automatic purchase orders.'),can('suppliers',true)?btn('+ Link supplier','id="link-supplier"','small'):'');}
 if(table==='projects'){const docs=[];for(const [kind,route]of Object.entries(kindRoute))if(can(route))docs.push(...(await api('/documents?kind='+kind)).filter(d=>d.project_id===id));extra=panel('Project documents',docs.length?docTable(docs):empty('No documents linked','Select this project when creating a document.'));if(state.privateCosts){const inv=docs.filter(d=>d.kind==='invoice'&&!['Draft','Void'].includes(d.status));const revenue=inv.reduce((s,d)=>s+Number(d.subtotal_cents)*Number(d.exchange_rate),0),cost=inv.reduce((s,d)=>s+Number(d.cost_cents)*Number(d.exchange_rate),0);extra=panel('Project profitability',`<div class="panel-body grid metrics">${metric('Invoiced sales',money(revenue))}${metric('Gross profit',money(revenue-cost))}</div>`)+extra;}}
 if(table==='suppliers'&&can('purchase_orders')){const docs=(await api('/documents?kind=purchase_order')).filter(d=>d.supplier_id===id);extra=panel('Purchase orders',docs.length?docTable(docs):empty('No purchase orders yet','Create a purchase order for this supplier.'));}
 render(head(r.company??r.name,btn('Back',`data-nav="${table}"`)+(canEdit?btn('Edit','id="edit-record"','primary'):''))+`<div class="details-grid"><div>${panel('Details',`<div class="panel-body"><dl class="details-list">${details}</dl></div>`)}</div><div>${extra}</div></div>`);if(canEdit)document.getElementById('edit-record').onclick=()=>recordEditor(table,r).catch(fail);if(document.getElementById('link-supplier'))document.getElementById('link-supplier').onclick=()=>supplierLinkEditor(r).catch(fail);
}
async function supplierLinkEditor(product){const suppliers=await getCatalog('suppliers',true);render(head('Link supplier to '+product.name,btn('Back','id="back-product"'))+`<form id="supplier-link-form" class="panel"><div class="panel-body"><div class="form-grid">${field('supplier_id','Supplier','text','',true,[{value:'',label:'Choose supplier'},...suppliers.map(s=>({value:s.id,label:s.name}))])}${field('supplier_sku','Supplier SKU')}${field('cost_cents','Supplier cost','number',0,true)}${field('currency','Currency','text','CAD',false,['CAD','USD','CNY','EUR'])}${field('minimum_quantity','Minimum quantity','number',1)}${field('lead_days','Lead time (days)','number',0)}${field('is_primary','Primary supplier','text','true',false,[{value:'true',label:'Yes'},{value:'false',label:'No'}])}${field('notes','Notes','textarea')}</div><div class="form-footer">${btn('Save source','type="submit"','primary')}</div></div></form>`);document.getElementById('back-product').onclick=()=>openRecord('products',product.id).catch(fail);document.getElementById('supplier-link-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.cost_cents=Math.round(Number(d.cost_cents)*100);d.minimum_quantity=Number(d.minimum_quantity);d.lead_days=Number(d.lead_days);d.is_primary=d.is_primary==='true';await post('/products/'+product.id+'/suppliers',d);toast('Supplier source saved');await openRecord('products',product.id);}catch(error){fail(error);}};}

async function documentEditor(kind,existing=null){const route=kindRoute[kind],po=kind==='purchase_order';const parties=await getCatalog(po?'suppliers':'customers',true);const products=can('products')?await getCatalog('products',true):[];const projects=can('projects')?await getCatalog('projects'):[];const settings=await api('/document-defaults');const d=existing??{issue_date:today(),due_date:plusDays(kind==='estimate'?settings.estimate_validity:settings.invoice_due_days),currency:'CAD',exchange_rate:1,customer_po:'',reference:'',ship_to:'',notes:'',terms:settings.payment_terms??'Net 30'};let lines=existing?existing.lines.map(l=>({...l,quantity:Number(l.quantity),unit_price_cents:Number(l.unit_price_cents),unit_cost_cents:Number(l.unit_cost_cents)})):[{product_id:null,sku:'',description:'',quantity:1,unit_price_cents:0,unit_cost_cents:0,discount_bps:0}];
 const title=({estimate:'Estimate',invoice:'Invoice',purchase_order:'Purchase Order',sales_order:'Sales Order'})[kind];
 render(head((existing?'Edit '+existing.number:'New '+title),btn('Back',`data-nav="${route}"`))+`<form id="document-form"><div id="document-error"></div><section class="panel"><div class="panel-body form-grid">${field(po?'supplier_id':'customer_id',po?'Supplier':'Customer','text',d[po?'supplier_id':'customer_id']??'',true,[{value:'',label:po?'Choose supplier':'Choose customer'},...parties.map(p=>({value:p.id,label:p.name??p.company}))])}${field('project_id','Project','text',d.project_id??'',false,[{value:'',label:'No project'},...projects.map(p=>({value:p.id,label:p.name}))])}${field('customer_po','Customer PO number','text',d.customer_po)}${field('reference','Reference / project name','text',d.reference)}${field('issue_date','Issue date','date',String(d.issue_date).slice(0,10),true)}${field('due_date',po?'Expected delivery':kind==='estimate'?'Expiration date':'Due date','date',d.due_date?String(d.due_date).slice(0,10):'')}${field('currency','Currency','text',d.currency,false,['CAD','USD','CNY','EUR'])}${field('exchange_rate','CAD per unit of document currency','number',Number(d.exchange_rate??1),true,null,false,'Example: CAD document = 1; enter the agreed rate for foreign currency.')}${field('ship_to','Ship-to address','textarea',d.ship_to??'',false,null,true)}</div></section><section class="panel section-gap"><div class="panel-head"><h2>Line items</h2>${btn('+ Add line','type="button" id="add-line"','small')}</div><div class="table-wrap"><table class="line-editor"><thead><tr><th>Product / description</th><th>SKU</th><th>Qty</th><th>${po?'Unit cost':'Unit price'}</th><th>Discount %</th>${state.privateCosts?'<th>Private unit cost</th>':''}<th>Total</th><th></th></tr></thead><tbody id="line-body"></tbody></table></div><div class="panel-body"><div class="inline-fields">${field('tax1_name','Tax component 1','text',settings.default_tax[0]?.name??'')}${field('tax1_rate','Rate (%)','number',(settings.default_tax[0]?.rate_bps??0)/100)}${field('tax2_name','Tax component 2','text',settings.default_tax[1]?.name??'')}${field('tax2_rate','Rate (%)','number',(settings.default_tax[1]?.rate_bps??0)/100)}</div><div class="totals" id="editor-totals"></div></div></section><section class="panel section-gap"><div class="panel-body form-grid">${field('notes','Notes','textarea',d.notes??'')}${field('terms','Terms','textarea',d.terms??'')}</div></section><div class="form-footer">${btn('Cancel',`type="button" data-nav="${route}"`)}${btn(existing?'Save changes':'Create '+title,'type="submit"','primary')}</div></form>`);
 if(existing){document.querySelector('[name="tax1_name"]').value=existing.lines[0]?.taxes[0]?.name??'';document.querySelector('[name="tax1_rate"]').value=(existing.lines[0]?.taxes[0]?.rate_bps??0)/100;document.querySelector('[name="tax2_name"]').value=existing.lines[0]?.taxes[1]?.name??'';document.querySelector('[name="tax2_rate"]').value=(existing.lines[0]?.taxes[1]?.rate_bps??0)/100;}
 const totals=()=>{const form=new FormData(document.getElementById('document-form'));const party=parties.find(p=>p.id===form.get(po?'supplier_id':'customer_id'));let sub=0,tax=0;const rate=(Number(form.get('tax1_rate'))+Number(form.get('tax2_rate')))/100;for(const l of lines){const amount=Math.round(l.quantity*l.unit_price_cents*(1-l.discount_bps/10000));sub+=amount;const p=products.find(p=>p.id===l.product_id);if(!party?.tax_exempt&&p?.taxable!==false)tax+=Math.round(amount*Number(form.get('tax1_rate'))/100)+Math.round(amount*Number(form.get('tax2_rate'))/100);}document.getElementById('editor-totals').innerHTML=`<div><span>Subtotal</span><span>${money(sub,form.get('currency'))}</span></div><div><span>Tax</span><span>${money(tax,form.get('currency'))}</span></div><div class="grand"><span>Total</span><span>${money(sub+tax,form.get('currency'))}</span></div>`;};
 const drawLines=()=>{document.getElementById('line-body').innerHTML=lines.map((l,i)=>`<tr data-line="${i}"><td class="description"><select data-line-field="product_id" aria-label="Line ${i+1} product"><option value="">Custom line</option>${products.map(p=>`<option value="${p.id}" ${l.product_id===p.id?'selected':''}>${E(p.sku+' · '+p.name)}</option>`).join('')}</select><input data-line-field="description" aria-label="Line ${i+1} description" placeholder="Description" value="${E(l.description)}" required></td><td><input data-line-field="sku" aria-label="Line ${i+1} SKU" value="${E(l.sku)}"></td><td class="qty"><input data-line-field="quantity" aria-label="Line ${i+1} quantity" type="number" min="0.001" step="0.001" value="${l.quantity}" required></td><td class="amount"><input data-line-field="unit_price_cents" aria-label="Line ${i+1} price" type="number" min="0" step="0.01" value="${l.unit_price_cents/100}" required></td><td class="qty"><input data-line-field="discount_bps" aria-label="Line ${i+1} discount" type="number" min="0" max="100" step="0.01" value="${l.discount_bps/100}"></td>${state.privateCosts?`<td class="amount"><input data-line-field="unit_cost_cents" aria-label="Line ${i+1} private cost" type="number" min="0" step="0.01" value="${Number(l.unit_cost_cents??0)/100}"></td>`:``}<td class="line-total">${money(Math.round(l.quantity*l.unit_price_cents*(1-l.discount_bps/10000)),document.querySelector('[name="currency"]').value)}</td><td>${btn('×',`type="button" data-remove="${i}" aria-label="Remove line ${i+1}"`,'small')}</td></tr>`).join('');bind('[data-line-field]','change',async e=>{const el=e.currentTarget,index=Number(el.closest('tr').dataset.line),key=el.dataset.lineField;const l=lines[index];if(key==='product_id'){l.product_id=el.value||null;const p=products.find(p=>p.id===l.product_id);if(p){l.sku=p.sku;l.description=p.description||p.name;l.unit_cost_cents=Number(p.cost_cents??0);const party=parties.find(p=>p.id===document.querySelector(`[name="${po?'supplier_id':'customer_id'}"]`).value);l.unit_price_cents=Number(po?p.cost_cents??0:party?.pricing_tier&&party.pricing_tier!=='Retail'?p.contractor_price_cents:p.list_price_cents);if(po&&can('suppliers')){try{const links=await api('/products/'+p.id+'/suppliers');const link=links.find(x=>x.supplier_id===party?.id);if(link){l.sku=link.supplier_sku;l.unit_price_cents=Number(link.cost_cents);}}catch(error){fail(error);}}}drawLines();}else{l[key]=['quantity','unit_price_cents','unit_cost_cents','discount_bps'].includes(key)?key==='quantity'?Number(el.value):Math.round(Number(el.value)*100):el.value;el.closest('tr').querySelector('.line-total').textContent=money(Math.round(l.quantity*l.unit_price_cents*(1-l.discount_bps/10000)),document.querySelector('[name="currency"]').value);totals();}});bind('[data-remove]','click',e=>{lines.splice(Number(e.currentTarget.dataset.remove),1);drawLines();});totals();};
 document.getElementById('add-line').onclick=()=>{lines.push({product_id:null,sku:'',description:'',quantity:1,unit_price_cents:0,unit_cost_cents:0,discount_bps:0});drawLines();};bind('[name="tax1_rate"],[name="tax2_rate"],[name="currency"],[name="customer_id"]','change',totals);drawLines();
 document.getElementById('document-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const taxes=[{name:data.tax1_name,rate_bps:Math.round(Number(data.tax1_rate)*100)},{name:data.tax2_name,rate_bps:Math.round(Number(data.tax2_rate)*100)}].filter(t=>t.name);for(const key of ['tax1_name','tax1_rate','tax2_name','tax2_rate'])delete data[key];data.kind=kind;data.exchange_rate=Number(data.exchange_rate);data.project_id=data.project_id||null;data.due_date=data.due_date||null;data.lines=lines.map(l=>({...l,taxes}));const saved=await api('/documents'+(existing?'/'+existing.id:''),{method:existing?'PUT':'POST',body:JSON.stringify(data)});toast(title+' saved');await openDocument(saved.id);}catch(error){document.getElementById('document-error').innerHTML=`<div class="error">${E(error.message)}</div>`;window.scrollTo(0,0);}finally{button.disabled=false;}};
}
const transitionMap={estimate:{Draft:['Sent','Accepted','Declined'],Sent:['Accepted','Declined','Expired'],Viewed:['Accepted','Declined','Expired'],Accepted:['Declined']},invoice:{Draft:['Sent','Void'],Sent:['Void'],Viewed:['Void'],Overdue:['Void']},purchase_order:{Draft:['Sent','Cancelled'],Sent:['Acknowledged','Cancelled'],Acknowledged:['Cancelled'],Received:['Closed']},sales_order:{New:['Approved','Cancelled'],Approved:['Waiting for Parts','Processing','Ready to Ship','Cancelled'],'Waiting for Parts':['Processing','Ready to Ship','Cancelled'],Processing:['Ready to Ship','Cancelled'],'Ready to Ship':['Cancelled'],Shipped:['Completed']}};
async function openDocument(id){const d=await api('/documents/'+id);state.current=d;state.route=kindRoute[d.kind];const write=can(state.route,true);const opts=transitionMap[d.kind]?.[d.status]??[];const pdfLink=`<a class="btn" href="/api/documents/${d.id}/pdf" target="_blank" rel="noopener">Download PDF</a>`;const edit=write&&['Draft','New'].includes(d.status)?btn('Edit draft','id="edit-document"'):'';const controls=write?`${btn('Duplicate','id="duplicate-document"')}${opts.length?`<select id="doc-status" aria-label="Change document status" class="btn"><option value="">Change status</option>${opts.map(s=>`<option>${E(s)}</option>`).join('')}</select>`:''}`:'';
 const conversions=write&&((d.kind==='estimate'&&['Accepted','Converted'].includes(d.status))||(d.kind==='sales_order'&&!['New','Cancelled'].includes(d.status))||(d.kind==='invoice'&&!['Draft','Void'].includes(d.status)))?['sales_order','invoice','purchase_order'].filter(k=>k!==d.kind&&!(d.kind==='sales_order'&&k==='sales_order')&&!(d.kind==='invoice'&&k!=='purchase_order')&&can(kindRoute[k],true)).map(k=>btn('Create '+({sales_order:'sales order',invoice:'invoice',purchase_order:'supplier PO'}[k]),`data-convert="${k}"`)).join(''):'';
 const cost=state.privateCosts?`<div class="notice">Private: cost ${money(d.cost_cents,d.currency)} · gross profit ${money(Number(d.subtotal_cents)-Number(d.cost_cents),d.currency)} · margin ${Number(d.subtotal_cents)?((Number(d.subtotal_cents)-Number(d.cost_cents))/Number(d.subtotal_cents)*100).toFixed(1):'0.0'}%. Cost information is excluded from customer PDFs.</div>`:'';
 const receive=write&&d.kind==='purchase_order'&&['Sent','Acknowledged','Partially Received'].includes(d.status)?btn('Receive parts','id="receive-parts"','primary'):'';const ship=write&&d.kind==='sales_order'&&d.status==='Ready to Ship'?btn('Record shipment','id="ship-order"','primary'):'';
 render(head(d.number,btn('Back',`data-nav="${state.route}"`)+pdfLink+edit+controls,({estimate:'Estimate',invoice:'Invoice',purchase_order:'Supplier purchase order',sales_order:'Sales order'})[d.kind])+`<div class="quick-actions">${badge(displayStatus(d))}${conversions}${receive}${ship}${d.kind==='invoice'&&d.balance_cents>0&&can('payments',true)&&!['Draft','Void'].includes(d.status)?btn('Record payment','id="record-payment"','primary'):''}</div>${cost}<section class="panel"><div class="doc-meta"><div><strong>${d.kind==='purchase_order'?'Supplier':'Customer'}</strong><p>${E(d.party_snapshot.name)}\n${E(d.party_snapshot.contact)}\n${E(d.party_snapshot.address)}\n${E(d.party_snapshot.email)}</p></div><div><strong>Details</strong><p>Issued ${E(String(d.issue_date).slice(0,10))}${d.due_date?'\n'+(d.kind==='estimate'?'Expires ':d.kind==='purchase_order'?'Expected ':'Due ')+E(String(d.due_date).slice(0,10)):''}\nCurrency ${E(d.currency)}\nCustomer PO ${E(d.customer_po||'—')}\nReference ${E(d.reference||'—')}</p></div><div><strong>Ship to</strong><p>${E(d.ship_to||d.party_snapshot.shipping_address||'—')}</p></div></div>${simpleTable(['SKU / Description','Qty',d.kind==='purchase_order'?'Unit cost':'Unit price','Discount','Line total',...(d.kind==='purchase_order'?['Received']:[])],d.lines.map(l=>[E(l.sku)+`<small>${E(l.description)}</small>`,E(Number(l.quantity)),money(l.unit_price_cents,d.currency),E(Number(l.discount_bps)/100+'%'),money(l.line_total_cents,d.currency),...(d.kind==='purchase_order'?[E(Number(l.received_quantity))]:[])]))}<div class="doc-footer"><div><p><strong>Notes</strong><br>${E(d.notes||'—')}</p><p><strong>Terms</strong><br>${E(d.terms||'—')}</p></div><div class="totals"><div><span>Subtotal</span><span>${money(d.subtotal_cents,d.currency)}</span></div><div><span>Tax</span><span>${money(d.tax_cents,d.currency)}</span></div><div class="grand"><span>Total</span><span>${money(d.total_cents,d.currency)}</span></div>${d.kind==='invoice'?`<div><span>Paid</span><span>${money(d.amount_paid_cents,d.currency)}</span></div><div><strong>Balance</strong><strong>${money(d.balance_cents,d.currency)}</strong></div>`:''}</div></div></section>${write?panel('Email document',`<div class="panel-body"><form id="email-form" class="inline-fields">${field('recipient','Recipient','email',d.party_snapshot.email,true)}${btn(d.email_logs.length?'Resend PDF':'Send PDF','type="submit"','primary')}</form><p class="subtle">The PDF is attached automatically. Delivery results are recorded below.</p></div>${d.email_logs.length?simpleTable(['Recipient','Status','Date','Result'],d.email_logs.map(l=>[E(l.recipient),badge(l.status),E(new Date(l.created_at).toLocaleString()),E(l.failure_reason??l.provider_id??'Awaiting provider')])):''}`):''}${d.payments.length?panel('Payment history',simpleTable(['Date','Method','Reference','Amount'],d.payments.map(p=>[E(String(p.date).slice(0,10)),E(p.method),E(p.reference),money(p.amount_cents,d.currency)]))):''}<footer>Revision ${d.revision} · Created ${E(new Date(d.created_at).toLocaleString())}. Prices and costs are saved with this document.</footer>`);
 if(document.getElementById('edit-document'))document.getElementById('edit-document').onclick=()=>documentEditor(d.kind,d).catch(fail);if(document.getElementById('duplicate-document'))document.getElementById('duplicate-document').onclick=async()=>{try{const result=await post('/documents/'+id+'/duplicate');toast('Draft duplicated');await openDocument(result.id);}catch(e){fail(e);}};
 if(document.getElementById('doc-status'))document.getElementById('doc-status').onchange=async e=>{if(!e.target.value)return;try{await api('/documents/'+id+'/status',{method:'PATCH',body:JSON.stringify({status:e.target.value})});await openDocument(id);toast('Status updated');}catch(error){fail(error);e.target.value='';}};
 bind('[data-convert]','click',async e=>{const b=e.currentTarget;b.disabled=true;try{const result=await post('/documents/'+id+'/convert',{kind:b.dataset.convert});toast(result.length+' document'+(result.length>1?'s':'')+' created');await openDocument(result[0].id);}catch(error){fail(error);}finally{b.disabled=false;}});
 if(document.getElementById('record-payment'))document.getElementById('record-payment').onclick=()=>paymentEditor(d).catch(fail);if(document.getElementById('email-form'))document.getElementById('email-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await post('/documents/'+id+'/email',{recipient:new FormData(e.target).get('recipient')});toast('Email accepted by provider');}catch(error){fail(error);}finally{await openDocument(id);}};
 if(document.getElementById('receive-parts'))document.getElementById('receive-parts').onclick=()=>receiptEditor(d);if(document.getElementById('ship-order'))document.getElementById('ship-order').onclick=async()=>{try{await post('/documents/'+id+'/ship',{key:crypto.randomUUID()});toast('Shipment recorded and inventory updated');state.catalog.products=null;await openDocument(id);}catch(error){fail(error);}};
}
function receiptEditor(d){const lines=d.lines.filter(l=>Number(l.quantity)>Number(l.received_quantity));render(head('Receive '+d.number,btn('Back','id="back-doc"'))+`<form id="receipt-form">${panel('Parts received',simpleTable(['Product','Ordered','Previously received','Receive now'],lines.map(l=>[E(l.sku+' · '+l.description),E(Number(l.quantity)),E(Number(l.received_quantity)),`<input class="btn" type="number" step="0.001" min="0" max="${Number(l.quantity)-Number(l.received_quantity)}" value="${Number(l.quantity)-Number(l.received_quantity)}" name="${l.id}" aria-label="Receive ${E(l.sku)}">`])))}<div class="form-footer">${btn('Record receipt','type="submit"','primary')}</div></form>`);document.getElementById('back-doc').onclick=()=>openDocument(d.id).catch(fail);const key=crypto.randomUUID();document.getElementById('receipt-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const received=[...new FormData(e.target)].filter(([id,q])=>Number(q)>0).map(([id,q])=>({id,quantity:Number(q)}));await post('/documents/'+d.id+'/receive',{key,lines:received});state.catalog.products=null;toast('Inventory received');await openDocument(d.id);}catch(error){fail(error);button.disabled=false;}};}
async function paymentsPage(){const rows=await api('/payments');render(head('Payments',can('payments',true)?btn('+ Record Payment','data-new="payments"','primary'):'')+panel('Recorded payments',rows.length?simpleTable(['Customer','Invoice','Date','Method','Reference','Amount'],rows.map(p=>[E(p.company),`<button class="doc-link" data-doc="${p.invoice_id}">${E(p.invoice_number)}</button>`,E(String(p.date).slice(0,10)),E(p.method),E(p.reference),money(p.amount_cents,p.currency)])):empty('No payments yet','Record customer payments against issued invoices.')));}
async function paymentEditor(invoice=null){const invoices=(await api('/documents?kind=invoice')).filter(d=>!['Void','Draft'].includes(d.status)&&Number(d.total_cents)>Number(d.amount_paid_cents));render(head('Record payment',btn('Back','data-nav="payments"'))+`<form id="payment-form" class="panel"><div class="panel-body"><div id="payment-error"></div><div class="form-grid">${field('invoice_id','Invoice','text',invoice?.id??'',true,[{value:'',label:'Choose invoice'},...invoices.map(d=>({value:d.id,label:d.number+' · '+d.party_snapshot.name+' · '+money(Number(d.total_cents)-Number(d.amount_paid_cents),d.currency)+' due'}))])}${field('date','Payment date','date',today(),true)}${field('amount_cents','Amount (invoice currency)','number',invoice?invoice.balance_cents/100:'',true)}${field('method','Payment method','text','E-transfer',false,['Credit Card','Cheque','E-transfer','ACH','Wire','Cash','Other'])}${field('reference','Reference')}${field('notes','Notes','textarea')}</div><div class="form-footer">${btn('Record payment','type="submit"','primary')}</div></div></form>`);const key=crypto.randomUUID();document.getElementById('payment-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type="submit"]');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.amount_cents=Math.round(Number(data.amount_cents)*100);data.key=key;const d=await post('/payments',data);toast('Payment recorded');await openDocument(d.id);}catch(error){document.getElementById('payment-error').innerHTML=`<div class="error">${E(error.message)}</div>`;b.disabled=false;}};}

async function reportsPage(from=today().slice(0,4)+'-01-01',to=today()){const r=await api('/reports?from='+from+'&to='+to);render(head('Reports','', 'Sales and profitability in CAD, excluding tax. Foreign-currency totals use each document’s saved exchange rate.')+`<form id="report-range" class="inline-fields">${field('from','From','date',from,true)}${field('to','To','date',to,true)}${btn('Update report','type="submit"','primary')}${btn('Export CSV','type="button" id="export-report"')}</form><div class="grid metrics section-gap">${metric('Invoiced sales',money(r.sales), 'Issued invoices',true)}${metric('Gross profit',money(r.profit),'Saved product costs')}${metric('Gross margin',r.margin.toFixed(1)+'%')}${metric('Estimate conversion',r.estimate_conversion_rate.toFixed(1)+'%')}</div><div class="report-tabs">${['monthly','yearly','customers','products','brands','suppliers','outstanding'].map((key,i)=>btn(({monthly:'Monthly sales',yearly:'Annual sales',customers:'Customers',products:'Products',brands:'Brands',suppliers:'Supplier spending',outstanding:'Outstanding'})[key],`data-report="${key}"`,i===0?'active':'')).join('')}</div><div id="report-table"></div>`);let active='monthly';const draw=key=>{active=key;document.querySelectorAll('[data-report]').forEach(b=>b.classList.toggle('active',b.dataset.report===key));const rows=r[key];document.getElementById('report-table').innerHTML=panel(key==='outstanding'?'Outstanding invoices':key==='suppliers'?'Supplier spending':'Sales and profitability',rows.length?key==='outstanding'?simpleTable(['Invoice','Customer','Due','Balance'],rows.map(d=>[E(d.number),E(d.name),E(String(d.due_date??'').slice(0,10)),money(d.balance,d.currency)])):simpleTable(key==='suppliers'?['Supplier','PO value','Orders']:['Group','Sales','Cost','Profit','Margin'],rows.map(d=>key==='suppliers'?[E(d.name),money(d.sales),E(d.count)]:[E(d.name),money(d.sales),money(d.cost),money(d.profit),d.margin.toFixed(1)+'%'])):empty('No report data in this period','Adjust the dates or create business documents.'));};draw('monthly');bind('[data-report]','click',e=>draw(e.currentTarget.dataset.report));document.getElementById('report-range').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);reportsPage(data.get('from'),data.get('to')).catch(fail);};document.getElementById('export-report').onclick=()=>{const rows=r[active];if(!rows.length)return toast('No rows to export');const columns=Object.keys(rows[0]);const csv=[columns,...rows.map(row=>columns.map(k=>row[k]))].map(row=>row.map(v=>{const str=String(v??'');return '"'+(/^[=+\-@]/.test(str)?"'":'')+str.replaceAll('"','""')+'"';}).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Elevated-'+active+'-'+from+'-'+to+'.csv';a.click();URL.revokeObjectURL(a.href);};}
async function settingsPage(){const s=await api('/settings');const users=await api('/users');const audit=await api('/audit');render(head('Settings')+`<div class="notice">Before issuing documents, set your business address, tax registration numbers, and the tax rates appropriate for each sale. No tax rate is pre-filled.</div><form id="settings-form">${panel('Business information',`<div class="panel-body form-grid">${field('business_name','Business name','text',s.business_name,true)}${field('email','Business email','email',s.email)}${field('business_address','Business address','textarea',s.business_address)}${field('ship_to','Default ship-to address','textarea',s.ship_to)}${field('phone','Phone','text',s.phone)}${field('tax_numbers','Tax registration numbers','text',s.tax_numbers)}${field('payment_terms','Default payment terms','text',s.payment_terms)}${field('invoice_due_days','Invoice due days','number',s.invoice_due_days)}${field('estimate_validity','Estimate validity (days)','number',s.estimate_validity)}${field('base_currency','Base currency','text',s.base_currency,false,['CAD'])}${field('pdf_footer','PDF footer','textarea',s.pdf_footer,false,null,true)}</div>`)}${panel('Default taxes',`<div class="panel-body form-grid">${field('tax1_name','Tax name','text',s.default_tax[0]?.name??'')}${field('tax1_rate','Tax rate (%)','number',(s.default_tax[0]?.rate_bps??0)/100)}${field('tax2_name','Additional tax name','text',s.default_tax[1]?.name??'')}${field('tax2_rate','Additional tax rate (%)','number',(s.default_tax[1]?.rate_bps??0)/100)}</div>`)}${panel('Email templates',`<div class="panel-body form-grid">${Object.entries(s.email_templates).map(([kind,t])=>field('subject_'+kind,kind.replaceAll('_',' ')+' subject','text',t.subject,false,null,true)+field('body_'+kind,'Message','textarea',t.body,false,null,true)).join('')}<div class="field wide"><small>Available placeholders: {{customer}}, {{number}}, {{project}}, {{total}}.</small></div></div>`)}<div class="form-footer">${btn('Save settings','type="submit"','primary')}</div></form>${panel('Team accounts',simpleTable(['Name','Email','Role','Status'],users.map(u=>[E(u.name),E(u.email),E(u.role),u.active?'Active':'Inactive'])),btn('+ Add user','id="add-user"','small'))}${panel('Audit history',audit.length?simpleTable(['When','Who','Action','Record'],audit.map(a=>[E(new Date(a.created_at).toLocaleString()),E(a.actor??'System'),E(a.action),E(a.entity_type)])):empty('No audit entries','Actions are recorded automatically.'))}<footer>Email delivery requires a verified sender and provider configuration. QuickBooks and website integrations are planned for a later version.</footer>`);document.getElementById('settings-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));const templates={};for(const kind of Object.keys(s.email_templates)){templates[kind]={subject:d['subject_'+kind],body:d['body_'+kind]};delete d['subject_'+kind];delete d['body_'+kind];}d.email_templates=templates;d.default_tax=[{name:d.tax1_name,rate_bps:Math.round(Number(d.tax1_rate)*100)},{name:d.tax2_name,rate_bps:Math.round(Number(d.tax2_rate)*100)}].filter(x=>x.name);for(const k of ['tax1_name','tax1_rate','tax2_name','tax2_rate'])delete d[k];d.estimate_validity=Number(d.estimate_validity);d.invoice_due_days=Number(d.invoice_due_days);await api('/settings',{method:'PUT',body:JSON.stringify(d)});toast('Settings saved');}catch(error){fail(error);}};document.getElementById('add-user').onclick=userEditor;}
function userEditor(){render(head('Add team member',btn('Back','data-nav="settings"'))+`<form id="user-form" class="panel"><div class="panel-body"><div class="form-grid">${field('name','Name','text','',true)}${field('email','Email','email','',true)}${field('password','Initial password','password','',true)}${field('role','Role','text','Sales',false,['Administrator','Sales','Accounting','Purchasing','Read Only'])}</div><div class="form-footer">${btn('Create account','type="submit"','primary')}</div></div></form>`);document.getElementById('user-form').onsubmit=async e=>{e.preventDefault();try{await post('/users',Object.fromEntries(new FormData(e.target)));toast('Team account created');await settingsPage();}catch(error){fail(error);}};}

initialize();
